// 同时后台静默重拉刷新（不阻塞本次渲染，下次进即最新）；无缓存才 await 真实请求。
let _filtersInflight: Record<string, Promise<FilterDictionaries | null> | undefined> = {};

async function _fetchFiltersFresh(key: string, path: string): Promise<FilterDictionaries | null> {
  // 同一 key 的并发请求复用同一个 in-flight Promise，避免重复打慢接口。
  if (_filtersInflight[key]) return _filtersInflight[key]!;
  const p = (async () => {
    try {
      const data = await fetchApi<FilterDictionaries>(path);
      if (data) {
        try { localStorage.setItem(key, JSON.stringify(data)); } catch { /* quota */ }
      }
      return data;
    } finally {
      _filtersInflight[key] = undefined;
    }
  })();
  _filtersInflight[key] = p;
  return p;
}

async function fetchFiltersCached(key: string, path: string): Promise<FilterDictionaries | null> {
  let cached: FilterDictionaries | null = null;
  try {
    const raw = localStorage.getItem(key);
    if (raw) cached = JSON.parse(raw) as FilterDictionaries;
  } catch { cached = null; }

  if (cached) {
    // 命中缓存：立即返回，后台静默刷新（不 await）。
    void _fetchFiltersFresh(key, path);
    return cached;
  }
  // 无缓存：必须等真实请求（首访才会经历这次慢加载）。
  return _fetchFiltersFresh(key, path);
}


