import React, { useState, useEffect, useRef } from 'react';

interface PosterImageProps {
  src?: string;
  alt?: string;
  className?: string;
  /** 加载失败（重试耗尽）时渲染的占位，由调用方决定样式。 */
  fallback?: React.ReactNode;
  /** 最大重试次数，默认 2。 */
  maxRetries?: number;
}

/**
 * 海报图，带失败自动重试。
 *
 * 背景：海报多为 image.tmdb.org 外链直连，国内访问不稳定。列表页一次并发几十张，
 * 偶发超时/连接失败就变灰块；重进或进详情（图少）又正常。后端正在把海报回填到
 * CDN（治本），这里先做前端缓解：onError 时隔一小段时间重试，并在 URL 上加
 * cache-busting query 强制重新请求（浏览器会缓存失败结果，不变 URL 重试无效）。
 * 重试耗尽才渲染 fallback 占位。
 */
export const PosterImage: React.FC<PosterImageProps> = ({ src, alt, className, fallback, maxRetries = 2 }) => {
  const [attempt, setAttempt] = useState(0);
  const [failed, setFailed] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // src 变化（换影片/翻页复用节点）时重置重试状态。
  useEffect(() => {
    setAttempt(0);
    setFailed(false);
  }, [src]);

  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);

  if (!src || failed) return <>{fallback ?? null}</>;

  // 重试时给 URL 追加 _r 参数绕过失败缓存；首次（attempt=0）用原始 URL，
  // 命中浏览器/CDN 缓存的成功结果。
  const resolvedSrc = attempt === 0
    ? src
    : `${src}${src.includes('?') ? '&' : '?'}_r=${attempt}`;

  return (
    <img
      key={resolvedSrc}
      src={resolvedSrc}
      alt={alt}
      referrerPolicy="no-referrer"
      className={className}
      onError={() => {
        if (attempt < maxRetries) {
          // 退避重试：第 1 次 ~400ms，第 2 次 ~800ms，给瞬时网络抖动恢复时间。
          const delay = 400 * (attempt + 1);
          if (timer.current) clearTimeout(timer.current);
          timer.current = setTimeout(() => setAttempt(a => a + 1), delay);
        } else {
          setFailed(true);
        }
      }}
    />
  );
};

